	WAVE_COMPLETE = 'WAVE_COMPLETE',
	PAUSED = 'PAUSED',
	GAME_OVER = 'GAME_OVER',
}

// ── Difficulty ──────────────────────────────────────────────────
export enum Difficulty {
	EASY = 'EASY',
	NORMAL = 'NORMAL',
	HARD = 'HARD',
}

